$ErrorActionPreference='Stop'; $root=Split-Path $PSScriptRoot -Parent; $s=Join-Path $root 'Cosmic-Realms-main\Server-src'
$threat=Get-Content (Join-Path $s 'wServer\realm\RealmThreatController.cs') -Raw; $featured=Get-Content (Join-Path $s 'wServer\realm\FeaturedDungeon.cs') -Raw; $realm=Get-Content (Join-Path $s 'wServer\realm\worlds\logic\Realm.cs') -Raw; $codex=Get-Content (Join-Path $s 'wServer\realm\DungeonCodex.cs') -Raw
foreach($x in 'Threat','100','20, 40, 60, 80, 100','Triggered.Add','1.0 + .50','threat_fragment','Reset','XpMultiplier','RareDropMultiplier','EchoDustBonusPercent','LastRewardDate','sigil_fragment'){if(($threat+$featured)-notmatch [regex]::Escape($x)){throw "Missing Phase 10 requirement: $x"}}
if($realm -notmatch '_threats.AddActivity' -or $realm -notmatch '_threats.Reset'){throw 'Threat lifecycle is not wired to Realm activity/reset.'}; if($codex -notmatch 'FeaturedDungeonService.RecordCompletion'){throw 'Featured first clear is not authoritative.'}; if(($threat+$featured)-match 'Mark of |PotionStorage|Forge'){throw 'Threats/Featured must not use marks, Potion Storage, or Forge.'}; Write-Host 'PASS: Realm Threat thresholds are per-Realm and deduplicated; Featured rotation/reward is UTC deterministic and mark-safe.'
